// Per-component Tailwind: appends each component's CSS (utilities.json rules +
// classes used in its own tsx) to its styleUrl output, so styles lazy-load with
// the component chunk instead of one big global CSS file.
// Third-party-lib selectors (flatpickr, filepond) must live with the component
// that imports the lib, so the styles ride the same chunk as the lib itself.
const fs = require('fs');
const path = require('path');
const tailwindcss = require('tailwindcss');
const twPlugin = require('tailwindcss/plugin');
const core = require('@salla.sa/twilight-tailwind-theme/plugin-core');
const generatorGlobals = require('@salla.sa/twilight-tailwind-theme/generator-globals');
const tokens = require('@salla.sa/twilight-tailwind-theme/component-tokens');
const postcss = require(require.resolve('postcss', {
  paths: [path.dirname(require.resolve('tailwindcss/package.json'))],
}));

const crypto = require('crypto');
const { isDevMode } = require('./commonjs-cache-fix');

const componentsDir = path.resolve(__dirname, '../components');
const CLASS_RE = /\.((?:[\w-]|\\.)+)/g;
const md5 = (s) => crypto.createHash('md5').update(s).digest('hex');

let cachedRules = null;
let aggregateSig = '';
// Pre-existing collisions, frozen as the central generator shipped them.
const KNOWN_COLLISIONS = new Set(['.s-modal-header']);

// Aggregate all utilities.json (same mapping as tailwind-theme/generator.js).
function allRules() {
  if (cachedRules && !isDevMode()) return cachedRules;
  const map = new Map(); // selector -> {owner, css}
  for (const dir of fs.readdirSync(componentsDir, { withFileTypes: true })) {
    if (!dir.isDirectory()) continue;
    let json;
    try {
      json = JSON.parse(fs.readFileSync(path.join(componentsDir, dir.name, 'utilities.json'), 'utf8'));
    } catch (e) {
      continue;
    }
    const owner = dir.name.replace('salla-', '');
    for (const [key, value] of Object.entries(json)) {
      const selector = typeof value === 'string'
        ? (key.startsWith('@at-root') ? key.replace('@at-root ', '') : `.s-${owner}-${key}`)
        : key;
      const prev = map.get(selector);
      if (prev && prev.owner !== owner && !KNOWN_COLLISIONS.has(selector)) {
        throw new Error(`utilities.json selector collision: "${selector}" is defined by both `
          + `salla-${prev.owner} and salla-${owner}; the aggregate is last-write-wins, so one `
          + `silently loses its rule. Scope the selector under your component's own class instead.`);
      }
      map.set(selector, { owner, css: typeof value === 'string' ? { [`@apply ${value}`]: {} } : value });
    }
  }
  cachedRules = [...map.entries()].map(([selector, r]) => ({ selector, ...r }));
  aggregateSig = md5(JSON.stringify(cachedRules));
  return cachedRules;
}

// Component dir state (tsx content scan + utilities.json) for cache invalidation.
function dirSignature(dirName) {
  const dir = path.join(componentsDir, dirName);
  return fs.readdirSync(dir)
    .filter((f) => /\.(tsx|ts|json)$/.test(f))
    .map((f) => f + ':' + fs.statSync(path.join(dir, f)).mtimeMs)
    .join('|');
}

// Candidate classes that force-emit this component's rules (covers `s-x-${dynamic}` names).
function safelistFor(owner) {
  const own = `s-${owner}`;
  const out = new Set();
  for (const rule of allRules()) {
    if (rule.owner !== owner) continue;
    const classes = Array.from(rule.selector.matchAll(CLASS_RE), (m) => m[1].replace(/\\/g, ''));
    const owned = classes.filter((c) => c === own || c.startsWith(`${own}-`));
    for (const c of owned.length ? owned : classes) out.add(c);
  }
  return [...out];
}

// Own rules + foreign rules that mention this component's classes.
function rulesFor(owner) {
  const own = `s-${owner}`;
  return allRules().filter((rule) => {
    if (rule.owner === owner) return true;
    return Array.from(rule.selector.matchAll(CLASS_RE), (m) => m[1].replace(/\\/g, ''))
      .some((c) => c === own || c.startsWith(`${own}-`));
  });
}

function tailwindConfigFor(owner, dirName) {
  const componentPlugin = twPlugin((api) => {
    core.handler(api);
    api.addUtilities(generatorGlobals);
    api.addUtilities(rulesFor(owner).map((r) => ({ [r.selector]: r.css })));
  }, core.config);

  return {
    important: false,
    darkMode: 'class',
    corePlugins: { preflight: false, outline: false },
    content: [
      path.join(componentsDir, dirName, '**/*.{tsx,ts}'),
      '!' + path.join(componentsDir, dirName, '**/test/**'),
    ],
    safelist: safelistFor(owner),
    theme: tokens,
    plugins: [componentPlugin],
  };
}

// Stencil compiles styles once per output target (dist, custom-elements,
// hydrate): share one compute per input state instead of running 3x.
const resultCache = new Map(); // `${fileName}:${dirName}` -> {key, promise}

exports.tailwindPerComponent = () => ({
  name: 'tailwind-per-component',
  pluginType: 'css',
  async transform(sourceText, fileName) {
    if (process.env.TWPC_DEBUG) console.log('TWPC transform:', fileName);
    // Stencil passes sass output as .css (original styleUrl is .scss).
    if (!fileName || !/\.s?css$/.test(fileName)) return null;
    const rel = path.relative(componentsDir, fileName);
    if (rel.startsWith('..')) return null;
    const [dirName, base] = rel.split(path.sep);
    // Utilities ride the main component file only (sub-component scss pass through).
    if (base !== `${dirName}.css` && base !== `${dirName}.scss`) return null;
    const owner = dirName.replace('salla-', '');
    allRules();
    const key = md5(sourceText) + aggregateSig + md5(dirSignature(dirName));
    // Key by file + dir: dir drives owner/config, several components share one styleUrl.
    const cacheKey = `${fileName}:${dirName}`;
    const hit = resultCache.get(cacheKey);
    if (hit && hit.key === key) return { code: await hit.promise };
    const promise = postcss([tailwindcss(tailwindConfigFor(owner, dirName))])
      .process(`${sourceText}\n@tailwind utilities;\n`, { from: fileName })
      .then((result) => {
        if (isDevMode()) console.log(`✅ [utilities] ${dirName} compiled (${Math.round(result.css.length / 1024)}kb)`);
        // Marker lets the global script keep this chunk's <style> ahead of the theme css.
        return `/*!twlt*/${result.css}`;
      });
    resultCache.set(cacheKey, { key, promise });
    return { code: await promise };
  },
});
